
import type { MoneyValue } from './MoneyValue.js';
import type { PromotionCombinesWith } from './PromotionCombinesWith.js';
import type { PromotionExclusivity } from './PromotionExclusivity.js';

export type PromotionCandidate = { /** Calculated discount amount for this promotion candidate before final application, when available. */ "amount_money"?: MoneyValue; /** Discount amount applied to the order for candidates in applied[]. */ "applied_money"?: MoneyValue; "combines_with"?: PromotionCombinesWith; /** Current money amount counted toward threshold_money for available[] candidates. */ "current_money"?: MoneyValue; "customer_facing_name": string; "discount_class"?: "order" | "line_item" | "service_charge" | (string & {}); "exclusivity"?: PromotionExclusivity; /** Additional money amount needed to reach threshold_money for available[] candidates. */ "gap_money"?: MoneyValue; "order_charge_ids"?: Array<string>; "order_line_item_ids"?: Array<string>; "promotion_code"?: string; "promotion_code_id"?: string; "promotion_decline_reason"?: "already_applied" | "automatic_disabled" | "buy_item_missing" | "code_invalid" | "code_required" | "codes_disabled" | "currency_mismatch" | "disabled" | "exhausted" | "expired" | "max_promotions_reached" | "minimum_not_met" | "no_discountable_balance" | "not_combinable" | "not_eligible" | "not_yet_started" | "superseded" | "superseded_by_better_offer" | "unknown_type" | (string & {}); "promotion_id": string; "stacking_mode"?: "continue" | "stop_after" | (string & {}); /** Minimum money amount required by a threshold rule for available[] candidates. */ "threshold_money"?: MoneyValue; /** Discount amount this candidate would have applied if it had been eligible and won conflict resolution. */ "would_have_applied_money"?: MoneyValue; };
